function read(id){if(id==="training"){try{const data=JSON.parse(localStorage.getItem("deputy7_dept2_training_v1")||"{}");return (Array.isArray(data.courses)?data.courses:[]).map(c=>({id:c.id,title:c.title,category:c.category,owner:c.coordinator||c.organizer||"—",status:c.status,date:c.startDateFa||c.startDate||"—",due:c.endDateFa||c.endDate||"—",description:c.description||c.outcomes||""}));}catch(e){return []}}try{const v=localStorage.getItem(key(id));if(v===null){const seed=samples[id]||[];localStorage.setItem(key(id),JSON.stringify(seed));return seed.map(x=>({...x}));}const a=JSON.parse(v);return Array.isArray(a)?a:[]}catch(e){return (samples[id]||[]).map(x=>({...x}));}}
function write(id,rows){try{localStorage.setItem(key(id),JSON.stringify(rows));return true}catch(e){alert("ذخیره‌سازی در این مرورگر در دسترس نیست.");return false}}
modules.forEach(m=>{const rows=read(m.id);if(!["training","processes"].includes(m.id)&&rows.length){const normalized=rows.map(x=>({...x,department:window.Deputy7Registry?.departmentName(x.department||"اداره تحقیق و توسعه")||x.department||"اداره تحقیق و توسعه"}));if(rows.some((x,i)=>x.department!==normalized[i].department))write(m.id,normalized)}});
function pageUrl(file){return new URL(file,location.href).href}function href(id,v){const u=new URL("department-2.html",location.href);u.searchParams.set("module",id);u.searchParams.set("view",v);return u.href}
function side(){const items=[{id:"home",label:"نمای کلی اداره",url:pageUrl("department-2.html"),icon:"⌂",direct:true},...modules.map((m,i)=>({id:m.id,label:m.title,icon:String(i+1).padStart(2,"0").replace(/[0-9]/g,d=>"۰۱۲۳۴۵۶۷۸۹"[+d]),children:m.id==="training"?[{label:"بانک دوره‌های آموزشی",url:href("training","courses"),active:isModule&&moduleId==="training"&&view==="courses"},{label:"فراگیران و اساتید",url:href("training","people"),active:isModule&&moduleId==="training"&&view==="people"},{label:"گزارش‌ها و تحلیل‌ها",url:href("training","reports"),active:isModule&&moduleId==="training"&&view==="reports"},{label:"تنظیمات و دسته‌بندی‌ها",url:href("training","settings"),active:isModule&&moduleId==="training"&&view==="settings"}]:m.subs.map(([v,t])=>({label:t,url:href(m.id,v),active:isModule&&m.id===moduleId&&v===view}))})),{id:"back",label:"بازگشت به درگاه معاونت ۷",url:pageUrl("../dashboard.html"),icon:"↩",direct:true}];const nav=items.map(x=>{const active=x.id==="home"?!isModule:x.id==="back"?false:isModule&&x.id===moduleId;const has=!!x.children;const expanded=has&&isModule&&x.id===moduleId;return '<div class="d2-nav-group '+(active?'is-active ':'')+(expanded?'has-open':'')+'"><div class="d2-nav-row">'+(has?'<a class="d2-nav-link" href="'+(x.id==="training"?href("training","dashboard"):href(x.id,x.id==="registry"?"departments":"bank"))+'" data-branch="true" aria-expanded="'+expanded+'" title="'+x.label+'"><span class="d2-nav-icon">'+x.icon+'</span><span class="d2-nav-label">'+x.label+'</span></a>':'<a class="d2-nav-link" href="'+x.url+'" title="'+x.label+'"><span class="d2-nav-icon">'+x.icon+'</span><span class="d2-nav-label">'+x.label+'</span></a>')+'</div>'+(has?'<div class="d2-nav-sub '+(expanded?'is-open':'')+'">'+x.children.map(c=>'<a class="d2-nav-sub-link '+(c.active?'active':'')+'" href="'+c.url+'">'+c.label+'</a>').join("")+'</div>':'')+'</div>'}).join("");return '<aside class="dept2-sidebar menu-expanded" aria-label="منوی کناری اداره تحقیق و توسعه"><button class="d2-menu-toggle" type="button" aria-label="جمع یا باز کردن منو" aria-expanded="true"><span></span><span></span><span></span></button><div class="d2-side-brand"><span class="d2-brand-mark">۰۲</span><div class="d2-brand-text"><b>تحقیق و توسعه</b><small>معاونت ۷ · اداره تخصصی</small></div></div><nav class="d2-side-nav" aria-label="بخش‌های اداره">'+nav+'</nav></aside>'}
const legacy=document.createElement("details");legacy.className="dept2-legacy";legacy.innerHTML="<summary>مشاهده اطلاعات و امکانات قبلی اداره</summary><div class=\"dept2-legacy-content\"></div>";
const old=[...root.children];old.forEach(n=>legacy.querySelector(".dept2-legacy-content").append(n));
root.className="dept2-layout";
root.innerHTML="";
document.querySelectorAll("body > .dept2-sidebar").forEach(node=>node.remove());const sideHost=document.createElement("div");sideHost.innerHTML=side();const sidebar=sideHost.firstElementChild;document.body.append(sidebar);document.body.classList.add("dept2-workspace-page");document.body.classList.add("d2-menu-body-expanded");const toggle=sidebar.querySelector(".d2-menu-toggle");toggle.addEventListener("click",()=>{const expanded=!sidebar.classList.contains("menu-expanded");sidebar.classList.toggle("menu-expanded",expanded);sidebar.classList.toggle("menu-collapsed",!expanded);document.body.classList.toggle("d2-menu-body-expanded",expanded);toggle.setAttribute("aria-expanded",String(expanded));});sidebar.querySelectorAll("[data-branch]").forEach(link=>link.addEventListener("click",e=>{e.preventDefault();const group=link.closest(".d2-nav-group"),sub=group.querySelector(":scope > .d2-nav-sub");const open=sub.classList.toggle("is-open");group.classList.toggle("has-open",open);link.setAttribute("aria-expanded",String(open));}));if(matchMedia("(max-width:850px)").matches){sidebar.classList.remove("menu-expanded");sidebar.classList.add("menu-collapsed");document.body.classList.remove("d2-menu-body-expanded");const mobile=document.createElement("button");mobile.className="d2-mobile-menu";mobile.type="button";mobile.setAttribute("aria-label","باز کردن منوی کناری");mobile.textContent="☰";const overlay=document.createElement("div");overlay.className="d2-menu-overlay";document.body.append(mobile,overlay);const close=()=>{sidebar.classList.remove("is-open");overlay.classList.remove("is-open");};mobile.addEventListener("click",()=>{sidebar.classList.add("is-open");overlay.classList.add("is-open");});overlay.addEventListener("click",close);sidebar.querySelectorAll(".d2-nav-sub-link,.d2-nav-group:not(:has([data-branch])) .d2-nav-link").forEach(link=>link.addEventListener("click",close));}
const main=document.createElement("section");main.className="dept2-main";root.append(main);
if(isModule)renderModule(main);else renderHome(main);
