function detail(x){selected=x.id;$("#idea-stage",main).innerHTML='<section class="d2x-panel d2x-detail d2x-idea-detail"><div class="d2x-panel-head"><div><span class="d2x-sample">'+(x.sample?"نمونه آزمایشی":"پرونده ثبت‌شده")+'</span><h2>'+safe(x.title)+'</h2><p>'+safe(x.category)+' · '+safe(x.status)+' · اولویت '+safe(x.priority)+'</p></div><div><button class="d2x-small" id="idea-edit-selected">ویرایش پرونده</button> <button class="d2x-small" id="idea-close">بازگشت به بانک</button></div></div><div class="d2x-meta"><div><small>اداره مرتبط</small><b>'+safe(x.department||"تعیین نشده")+'</b></div><div><small>پیشنهاددهنده</small><b>'+safe(x.proposer)+'</b></div><div><small>واحد مرتبط</small><b>'+safe(x.unit)+'</b></div><div><small>تاریخ ثبت</small><b>'+safe(x.date)+'</b></div><div><small>مسئول اجرا</small><b>'+safe(x.implementationOwner)+'</b></div></div><h3>مسئله / نیاز</h3><p>'+safe(x.problem)+'</p><h3>راهکار پیشنهادی</h3><p class="d2x-quote">'+safe(x.solution)+'</p><h3>منافع مورد انتظار</h3><p>'+safe(x.benefit)+'</p><div class="d2x-idea-assessment"><div><small>منابع</small><b>'+safe(x.resources)+'</b></div><div><small>هزینه</small><b>'+safe(x.cost)+'</b></div><div><small>امکان‌پذیری</small><b>'+safe(x.feasibility)+'</b></div><div><small>میزان اثر</small><b>'+safe(x.impact)+'</b></div></div><h3>ریسک‌ها و محدودیت‌ها</h3><p>'+safe(x.risk)+'</p><h3>ارزیابی کارشناسی و تصمیم</h3><p>'+safe(x.evaluation)+'</p><p>'+safe(x.decision)+'</p><div class="d2x-proposal"><b>برنامه پیگیری</b><p>مسئول: '+safe(x.implementationOwner||"تعیین نشده")+' · مهلت: '+safe(x.due||"تعیین نشده")+'</p><p>'+safe(x.notes)+'</p></div></section>';
$("#idea-edit-selected",main).onclick=()=>form(rows.find(y=>y.id===selected));$("#idea-close",main).onclick=render;
}
render();if(view==="new")form();
